{
  if ((args || '').trim() === 'help' || (args || '').trim() === '--help' || (args || '').trim() === '-h') {
    return { output: `advisor — 配置 advisor 模型\n用法: /advisor`.trim(), truncated: false }
  }
  const arg = args.trim().toLowerCase()
  const baseModel = parseUserSpecifiedModel(
    context.getAppState().mainLoopModel ?? getDefaultMainLoopModelSetting(),
  )

  if (!arg) {
    const current = context.getAppState().advisorModel
    if (!current) {
      return {
        type: 'text',
        value:
          'Advisor: 未设置\n使用 "/advisor <模型>" 启用（例如 "/advisor opus"）。',
      }
    }
    if (!modelSupportsAdvisor(baseModel)) {
      return {
        type: 'text',
        value: `⚠️ Advisor: ${current}（未激活）\n当前模型（${baseModel}）不支持 advisor。`,
      }
    }
    return {
      type: 'text',
      value: `ℹ️ Advisor: ${current}\n使用 "/advisor unset" 禁用或 "/advisor <模型>" 更改。`,
    }
  }

  if (arg === 'unset' || arg === 'off') {
    const prev = context.getAppState().advisorModel
    context.setAppState(s => {
      if (s.advisorModel === undefined) return s
      return { ...s, advisorModel: undefined }
    })
    updateSettingsForSource('userSettings', { advisorModel: undefined })
    return {
      type: 'text',
      value: prev
        ? `✅ 已禁用 Advisor（之前是 ${prev}）。`
        : 'ℹ️ Advisor 已经是未设置状态。',
    }
  }

  const normalizedModel = normalizeModelStringForAPI(arg)
  const resolvedModel = parseUserSpecifiedModel(arg)
  const { valid, error } = await validateModel(resolvedModel)
  if (!valid) {
    return {
      type: 'text',
      value: error
        ? `无效的 advisor 模型：${error}`
        : `未知模型：${arg}（${resolvedModel}）`,
    }
  }

  if (!isValidAdvisorModel(resolvedModel)) {
    return {
      type: 'text',
      value: `❌ 模型 ${arg}（${resolvedModel}）不能用作 advisor`,
    }
  }

  context.setAppState(s => {
    if (s.advisorModel === normalizedModel) return s
    return { ...s, advisorModel: normalizedModel }
  })
  updateSettingsForSource('userSettings', { advisorModel: normalizedModel })

  if (!modelSupportsAdvisor(baseModel)) {
    return {
      type: 'text',
      value: `⚠️ Advisor 已设置为 ${normalizedModel}。\n注意：您当前的模型（${baseModel}）不支持 advisor。切换到支持的模型以使用 advisor。`,
    }
  }

  return {
    type: 'text',
    value: `✅ Advisor 已设置为 ${normalizedModel}。`,
  }
}

{
  const s = (args ?? '').trim()
  const parts = s.match(/^(\S+)\s*([\s\S]*)$/)
  const subCommand = parts?.[1]?.toLowerCase() ?? ''
  const subArgs = parts?.[2] ?? ''

  switch (subCommand) {
    case 'create':
      return { type: 'text', value: await handleCreate(subArgs) }
    case 'list':
    case 'ls':
      return { type: 'text', value: handleList(subArgs) }
    case 'edit':
      return { type: 'text', value: handleEdit(subArgs) }
    case 'delete':
    case 'rm':
    case 'remove':
      return { type: 'text', value: handleDelete(subArgs) }
    case 'use':
      return { type: 'text', value: handleUse(subArgs) }
    case 'export':
      return { type: 'text', value: handleExport(subArgs) }
    case 'import':
      return { type: 'text', value: handleImport(subArgs) }
    case 'templates':
    case 'template':
    case 'tmpl':
      return { type: 'text', value: handleTemplates() }
    case 'help':
    case '--help':
    case '-h':
    case '':
    default:
      return { type: 'text', value: renderHelp() }
  }
}

{
  const s = (args ?? '').trim()

  if (!s || s.includes('--help')) {
    return {
      type: 'text',
      value: [
        '🌐 REST API Debug Client',
        '',
        '📖 用法: ',
        '  /api-debug <METHOD> <URL> [BODY]    发送请求',
        '  /api-debug history                  查看请求历史',
        '  /api-debug clear                    清除历史',
        '',
        '选项:',
        '  --header KEY=VALUE   添加请求头（可多次使用）',
        '  --timeout MS         超时时间（毫秒，默认 30000）',
        '  --no-body           不显示响应体',
        '',
        '💡 示例: ',
        '  /api-debug GET https://api.example.com/users',
        '  /api-debug POST https://api.example.com/users {"name":"test"}',
        '  /api-debug GET https://api.example.com/users --header Authorization=Bearer TOKEN',
        '  /api-debug history',
      ].join('\n'),
    }
  }

  const parts = s.split(/\s+/)
  const subCommand = parts[0]?.toLowerCase()

  // 子命令
  if (subCommand === 'history') {
    return showHistory()
  }
  if (subCommand === 'clear') {
    return clearHistory()
  }

  // 解析 HTTP 请求
  const method = (parts[0]?.toUpperCase() || 'GET') as 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH' | 'HEAD' | 'OPTIONS'
  const url = parts[1]

  if (!url) {
    return {
      type: 'text',
      value: '❌ 请提供 URL\n\n用法: /api-debug <METHOD> <URL> [BODY]\n示例: /api-debug GET https://api.example.com/users',
    }
  }

  // 解析选项
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'User-Agent': 'doge-code-api-debug/1.0',
  }

  let body: string | undefined
  let showBody = true

  for (let i = 2; i < parts.length; i++) {
    if (parts[i] === '--header' && i + 1 < parts.length) {
      const headerValue = parts[++i]
      const eqIndex = headerValue.indexOf('=')
      if (eqIndex > 0) {
        const key = headerValue.slice(0, eqIndex)
        const value = headerValue.slice(eqIndex + 1)
        headers[key] = value
      }
    } else if (parts[i] === '--no-body') {
      showBody = false
    } else if (parts[i] === '--timeout' && i + 1 < parts.length) {
      // timeout handled via AbortSignal if needed
      i++
    } else if (!parts[i].startsWith('--')) {
      // Treat as body
      body = parts.slice(i).join(' ')
      break
    }
  }

  try {
    const record = await executeRequest(method, url, headers, body)
    addToHistory(record)

    return {
      type: 'text',
      value: formatRequestRecord(record, showBody),
    }
  } catch (error) {
    return {
      type: 'text',
      value: `❌ 请求失败: ${error instanceof Error ? error.message : '未知错误'}\n\nURL: ${url}\nMethod: ${method}`,
    }
  }
}

{
  if ((args || '').trim() === 'help' || (args || '').trim() === '--help' || (args || '').trim() === '-h') {
    return { output: `api-doc — Next.js App Router handler\n用法: /api-doc`.trim(), truncated: false }
  }
  const p = args.trim().split(/\s+/)
  const c = p[0] || ''
  if (!c) return { type: 'text', value: [
    '📖 API 文档生成器', '', '📖 用法：',
    '  /api-doc gen <文件> [格式]    生成文档 (md/html/json)',
    '  /api-doc scan <目录>             扫描目录中的 API',
    '  /api-doc routes <文件>          提取路由',
    '  /api-doc jsdoc <文件>           提取 JSDoc 注释',
    '  /api-doc openapi <文件>         解析 OpenAPI 规范',
    '  /api-doc sigs <文件>            提取函数签名（参数/返回类型）',
    '  /api-doc classes <文件>         提取类',
    '  /api-doc interfaces <文件>      提取接口',
    '  /api-doc types <文件>           提取类型别名 (AST)',
    '  /api-doc exports <文件>         列出所有导出',
    '  /api-doc all [目录]              完整项目文档',
  ].join('\n') }

  let r = ''

  if (c === 'gen') {
    const file = p[1]; const format = p[2] || 'md'
    if (!file || !existsSync(file)) return { type: 'text', value: '❌ 未找到文件：' + (file || '') }
    const content = readFileSync(file, 'utf-8')
    const endpoints = [...extractJSdocs(content), ...extractRoutes(content, 'express'), ...extractRoutesAdvanced(content)]
    const title = basename(file, extname(file))
    if (endpoints.length === 0) {
      // Try to extract function-like declarations as API endpoints
      const funcRegex = /(?:export\s+)?(?:async\s+)?function\s+(\w+)\s*\([^)]*\)/g
      const classRegex = /(?:export\s+)?class\s+(\w+)/g
      let match
      while ((match = funcRegex.exec(content)) !== null) {
        endpoints.push({ name: match[1], method: '', path: '', description: '', params: [], returnType: '', file: file, line: content.substring(0, match.index).split('\n').length })
      }
      while ((match = classRegex.exec(content)) !== null) {
        endpoints.push({ name: match[1], method: '', path: '', description: 'Class', params: [], returnType: '', file: file, line: content.substring(0, match.index).split('\n').length })
      }
    }
    if (format === 'html') { r = generateHTML(title, endpoints) }
    else if (format === 'json') { r = JSON.stringify(endpoints, null, 2) }
    else {
      r = generateMarkdown(title, endpoints)
      const sigDoc = generateSignaturesMarkdown(file, extractFunctionSignatures(content))
      if (sigDoc) r += '\n' + sigDoc
      const typeDoc = generateTypesMarkdown(file, extractTypesAST(content))
      if (typeDoc) r += '\n' + typeDoc
    }
  }

  else if (c === 'sigs') {
    const file = p[1]
    if (!file || !existsSync(file)) return { type: 'text', value: '❌ 未找到文件：' + (file || '') }
    const sigs = extractFunctionSignatures(readFileSync(file, 'utf-8'))
    r = generateSignaturesMarkdown(file, sigs) || '💡 在 ' + file + ' 中未找到函数签名'
  }

  else if (c === 'types') {
    const file = p[1]
    if (!file || !existsSync(file)) return { type: 'text', value: '❌ 未找到文件：' + (file || '') }
    const types = extractTypesAST(readFileSync(file, 'utf-8'))
    r = generateTypesMarkdown(file, types) || '💡 在 ' + file + ' 中未找到类型声明'
  }

  else if (c === 'scan') {
    const dir = p[1] || '.'
    if (!existsSync(dir)) return { type: 'text', value: '❌ 未找到目录：' + dir }
    const allEndpoints: APIEndpoint[] = []
    const scan = (d: string) => {
      try {
        for (const item of readdirSync(d, { withFileTypes: true })) {
          const fp = join(d, item.name)
          if (item.isDirectory() && !item.name.startsWith('.') && item.name !== 'node_modules') scan(fp)
          else if (item.isFile() && /\.(ts|tsx|js|jsx)$/i.test(item.name)) {
            try {
              const content = readFileSync(fp, 'utf-8')
              allEndpoints.push(...extractJSdocs(content).map(e => ({ ...e, file: fp })))
              allEndpoints.push(...extractRoutes(content, 'express').map(e => ({ ...e, file: fp })))
              allEndpoints.push(...extractRoutesAdvanced(content).map(e => ({ ...e, file: fp })))
            } catch { /* ignore */ }
          }
        }
      } catch { /* ignore */ }
    }
    scan(dir)
    const lines = ['📊 API 扫描结果:', '==================', '', '✅ 共找到 ' + allEndpoints.length + ' 个端点:', '']
    allEndpoints.forEach(e => lines.push((e.method || 'FUNC') + ' ' + e.path + ' (' + e.file + ':' + e.line + ')'))
    r = lines.join('\n') || 'ℹ️ 无输出'
  }

  else if (c === 'routes') {
    const file = p[1]
    if (!file || !existsSync(file)) return { type: 'text', value: '❌ 未找到文件：' + (file || '') }
    const routes = extractRoutes(readFileSync(file, 'utf-8'), 'express')
    r = '📋 ' + file + ' 中的路由:\n' + routes.map(r => r.method + ' ' + r.path).join('\n')
  }

  else if (c === 'jsdoc') {
    const file = p[1]
    if (!file || !existsSync(file)) return { type: 'text', value: '❌ 未找到文件：' + (file || '') }
    const jsdocs = extractJSdocs(readFileSync(file, 'utf-8'))
    r = '📝 ' + file + ' 中的 JSDoc:\n' + jsdocs.map(j => '## ' + j.name + '\n' + j.description).join('\n\n')
  }

  else if (c === 'openapi') {
    const file = p[1]
    if (!file || !existsSync(file)) return { type: 'text', value: '❌ 未找到文件：' + (file || '') }
    try {
      const spec = JSON.parse(readFileSync(file, 'utf-8')) as OpenAPIInfo
      const lines = ['📖 OpenAPI: ' + spec.info?.title + ' v' + spec.info?.version, '📂 路径:', '']
      if (spec.paths) {
        for (const [path, methods] of Object.entries(spec.paths)) {
          for (const [method, info] of Object.entries(methods)) {
            lines.push(method.toUpperCase() + ' ' + path + ' - ' + (info.summary || ''))
          }
        }
      }
      r = lines.join('\n') || 'ℹ️ 无输出'
    } catch { r = '❌ JSON 格式无效：' + file }
  }

  else if (c === 'classes' || c === 'interfaces') {
    const file = p[1]
    if (!file || !existsSync(file)) return { type: 'text', value: '❌ 未找到文件：' + (file || '') }
    const content = readFileSync(file, 'utf-8')
    const regex = c === 'classes' ? /class\s+(\w+)/g : /interface\s+(\w+)/g
    const names: string[] = []
    let match
    while ((match = regex.exec(content)) !== null) names.push(match[1])
    r = (c === 'classes' ? '📦' : '🔗') + ' ' + file + ' 中的 ' + (c === 'classes' ? '类' : '接口') + ':\n' + (names.join('\n') || '💡 无')
  }

  else if (c === 'exports') {
    const file = p[1]
    if (!file || !existsSync(file)) return { type: 'text', value: '❌ 未找到文件：' + (file || '') }
    const content = readFileSync(file, 'utf-8')
    const exports = content.match(/export\s+(?:async\s+)?(?:function|const|class|interface|type|default)\s+(\w+)/g) || []
    r = '📦 ' + file + ' 中的导出:\n' + exports.map(e => '  ' + e.replace('export ', '')).join('\n')
  }

  else if (c === 'all') {
    const dir = p[1] || '.'
    const allEndpoints: APIEndpoint[] = []
    const scan = (d: string) => {
      try {
        for (const item of readdirSync(d, { withFileTypes: true })) {
          const fp = join(d, item.name)
          if (item.isDirectory() && !item.name.startsWith('.') && item.name !== 'node_modules') scan(fp)
          else if (item.isFile() && /\.(ts|tsx|js|jsx)$/i.test(item.name)) {
            try {
              const content = readFileSync(fp, 'utf-8')
              allEndpoints.push(...extractJSdocs(content).map(e => ({ ...e, file: fp })))
              allEndpoints.push(...extractRoutes(content, 'express').map(e => ({ ...e, file: fp })))
              allEndpoints.push(...extractRoutesAdvanced(content).map(e => ({ ...e, file: fp })))
            } catch { /* ignore */ }
          }
        }
      } catch { /* ignore */ }
    }
    scan(dir)
    r = generateMarkdown('📖 API 文档', allEndpoints)
  }

  else { r = '❌ 未知命令：' + c }

  return { type: 'text', value: r || 'ℹ️ 无输出' }
}

{
  const s = (args ?? '').trim()
  const parts = s.split(/\s+/)
  const cmd = parts[0]?.toLowerCase() || 'help'

  if (cmd === 'help' || cmd === '') return { type: 'text', value: ['📖 API 测试', '', '📖 用法：', '  /api-test run <name>             运行已保存的测试', '  /api-test run-all               运行全部测试', '  /api-test add                   添加新测试', '  /api-test list                  列出已保存测试', '  /api-test delete <name>         删除测试', '  /api-test quick <url>           快速 GET 请求', '  /api-test post <url> <body>     快速 POST 请求', '  /api-test history               测试运行历史', '  /api-test export                导出结果', '  /api-test collection <file>     导入集合', '  /api-test compare <a> <b>       对比响应', '  /api-test status <url>          检查端点状态', '  /api-test bench <url> [N]       基准测试端点', ''].join('\n') }

  if (cmd === 'run') {
    const name = parts.slice(1).join(' ')
    const tests = loadTests()
    const test = tests.find(t => t.name.toLowerCase().includes(name.toLowerCase()))
    if (!test) return { type: 'text', value: '❌ 未找到测试：' + name }
    try {
      const res = await httpRequestResolved(test.method, test.url, test.headers, test.body, 30000)
      // 支持自定义断言（tests 中可添加 assertions 数组）+ 响应 Schema 验证
      const assertions = (test as any).assertions
      const responseSchema = (test as any).responseSchema
      let passed: boolean
      let details: string
      if (assertions && assertions.length > 0) {
        const results = assertions.map((a: string) => ({ assertion: a, ok: evaluateAssertion(a, res) }))
        passed = results.every((r: any) => r.ok)
        details = results.map((r: any) => '  ' + (r.ok ? '✅' : '❌') + ' ' + r.assertion).join('\n')
        // 追加 schema 验证结果
        if (responseSchema) {
          let schemaErr: string | null = null
          try { schemaErr = validateJsonSchema(JSON.parse(res.body), responseSchema) } catch { schemaErr = '❌ 响应不是有效的 JSON' }
          if (schemaErr) { passed = false; details += '\n  ❌ Schema：' + schemaErr }
          else details += '\n  ✅ Schema 匹配'
        }
      } else if (responseSchema) {
        let schemaErr: string | null = null
        try { schemaErr = validateJsonSchema(JSON.parse(res.body), responseSchema) } catch { schemaErr = '❌ 响应不是有效的 JSON' }
        passed = res.status === test.expectedStatus && !schemaErr
        details = '  ℹ️ 期望：' + test.expectedStatus + '，实际：' + res.status + (schemaErr ? '\n  ❌ Schema：' + schemaErr : '')
      } else {
        passed = res.status === test.expectedStatus
        details = '  ℹ️ 期望：' + test.expectedStatus + '，实际：' + res.status
      }
      recordHistory(test.name, passed ? 'pass' : 'fail', res.durationMs)
      // 失败时显示响应体摘要（前 500 字符）
      let responseSummary = ''
      if (!passed) {
        const preview = res.body.length > 500 ? res.body.slice(0, 500) + '... (' + res.body.length + ' bytes)' : res.body
        responseSummary = '\n\n📄 响应预览：\n' + (preview || '(empty response)')
      }
      return { type: 'text', value: (passed ? '✅ 通过' : '❌ 失败') + ' ' + test.name + '\n' + details + '\n⏱️ 耗时：' + res.durationMs + 'ms' + responseSummary }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      return { type: 'text', value: '❌ 错误：' + msg }
    }
  }

  if (cmd === 'run-all') {
    const tests = loadTests()
    if (tests.length === 0) return { type: 'text', value: 'ℹ️ 暂无已保存测试。请使用 /api-test add 创建一个。' }
    const lines = ['🚀 正在运行 ' + tests.length + ' 个测试...', '']
    let passed = 0
    for (const t of tests) {
      try {
        const res = await httpRequest(t.method, t.url, t.headers, t.body, 15000)
        if (res.status === t.expectedStatus) { passed++; lines.push('✅ [通过] ' + t.name) }
        else lines.push('❌ [失败] ' + t.name + '（期望 ' + t.expectedStatus + '，实际 ' + res.status + '）')
        recordHistory(t.name, res.status === t.expectedStatus ? 'pass' : 'fail', res.durationMs)
      } catch (err) {
        lines.push('❌ [错误] ' + t.name + '：' + (err instanceof Error ? err.message : 'timeout'))
        recordHistory(t.name, 'error', 0)
      }
    }
    lines.push('', '📊 结果：' + passed + '/' + tests.length + ' 通过')
    return { type: 'text', value: lines.join('\n') }
  }

  if (cmd === 'add') {
    return { type: 'text', value: '💡 要添加测试，请在 ' + API_TESTS_DIR + ' 中创建 JSON 文件：\n{\n  "id": "test-1",\n  "name": "获取用户",\n  "method": "GET",\n  "url": "https://api.example.com/users",\n  "headers": {"Authorization": "Bearer token"},\n  "body": "",\n  "expectedStatus": 200,\n  "tags": ["users"]\n}' }
  }

  if (cmd === 'list') {
    const tests = loadTests()
    if (tests.length === 0) return { type: 'text', value: 'ℹ️ 暂无已保存测试' }
    const lines = ['📋 已保存的 API 测试：', '==================', '']
    tests.forEach(t => lines.push(t.method + ' ' + t.url + ' -> ' + t.expectedStatus + '（' + t.name + '）'))
    return { type: 'text', value: lines.join('\n') }
  }

  if (cmd === 'delete') {
    const name = parts.slice(1).join(' ')
    const tests = loadTests()
    const test = tests.find(t => t.name.toLowerCase().includes(name.toLowerCase()))
    if (!test) return { type: 'text', value: '❌ 未找到：' + name }
    try { require('fs').unlinkSync(join(API_TESTS_DIR, test.id + '.json')); return { type: 'text', value: '✅ 已删除：' + test.name } }
    catch { return { type: 'text', value: '❌ 删除失败' } }
  }

  if (cmd === 'quick') {
    const url = parts[1]
    if (!url) return { type: 'text', value: '📖 用法：/api-test quick <url>' }
    try {
      const res = await httpRequestResolved('GET', url)
      return { type: 'text', value: formatResponse(res) }
    } catch (err) {
      return { type: 'text', value: '❌ 错误：' + (err instanceof Error ? err.message : String(err)) }
    }
  }

  if (cmd === 'post') {
    const url = parts[1]; const body = parts.slice(2).join(' ')
    if (!url) return { type: 'text', value: '📖 用法：/api-test post <url> <body>' }
    try {
      const res = await httpRequest('POST', url, {}, body)
      return { type: 'text', value: formatResponse(res) }
    } catch (err) {
      return { type: 'text', value: '❌ 错误：' + (err instanceof Error ? err.message : String(err)) }
    }
  }

  if (cmd === 'history') {
    const historyFile = join(API_TESTS_DIR, 'history.json')
    if (!existsSync(historyFile)) return { type: 'text', value: 'ℹ️ 暂无测试历史。请先运行测试。' }
    try {
      const history = JSON.parse(readFileSync(historyFile, 'utf-8')) as Array<{ name: string; status: string; duration: number; timestamp: string }>
      const lines = ['📅 测试历史：', '==================', '']
      history.slice(-20).reverse().forEach((h: any) => lines.push(`[${h.status}] ${h.name}（${h.duration}ms）- ${h.timestamp}`))
