        setRefresh(k => k + 1)
        return
      }
      if (key.ctrl && input === 'h') {
        setMode('history')
        return
      }
      if (key.ctrl && input === 'g') {
        setMode('content')
        return
      }
      if (key.return && url) {
        await navigateTo(url)
        return
      }
      if (key.backspace || key.delete) {
        setUrl(prev => prev.slice(0, -1))
        setRefresh(k => k + 1)
        return
      }
      if (input && input.length === 1 && !key.ctrl && !key.meta && !key.alt) {
        setUrl(prev => prev + input)
        setRefresh(k => k + 1)
        return
      }
    }

    // History mode
    if (mode === 'history') {
      if (key.escape) {
        setMode('navigate')
        return
      }
      if (!isNaN(Number(input)) && Number(input) >= 1 && Number(input) <= history.length) {
        const entry = history[history.length - Number(input)]
        if (entry) {
          setUrl(entry.url)
          setMode('navigate')
          await navigateTo(entry.url)
        }
      }
    }

    // Content mode
    if (mode === 'content') {
      if (key.escape || key.ctrl && input === 'g') {
        setMode('navigate')
        return
      }
