    else if (parts[i] === '--min-relevance' && parts[i + 1]) { filters.minRelevance = parseInt(parts[i + 1]); i++ }
    else if (parts[i] === '--max-results' && parts[i + 1]) { filters.maxResults = parseInt(parts[i + 1]); i++ }
