      type: 'text',
      value: [
        '👁️ 文件监视已启动 (30秒)',
        '',
        '监视项目文件变化，自动更新文档索引...',
        `监视目录: ${root}`,
        '',
        '提示: 在此窗口按 Ctrl+C 停止监视',
      ].join('\n'),
    }
  }

  // ── 新命令: diff ──────────────────────────────────────────
  if (cmd === 'diff') {
    const diffParts = target.split(/\s+/)
    if (diffParts.length >= 2) {
      // 比较两个文件
      const result = diffDocs(diffParts[0], diffParts[1])
      return { type: 'text', value: result }
    } else if (diffParts.length === 1 && diffParts[0]) {
      // 比较 git 历史版本
      const result = diffGitVersions(diffParts[0])
      return { type: 'text', value: result }
    }
    return {
      type: 'text',
      value: '用法:\n  /wiki diff <文件1> <文件2>   比较两个文件\n  /wiki diff <文件>          比较 git 历史版本',
    }
  }

  // ── 新命令: template ──────────────────────────────────────────
  if (cmd === 'template') {
    const templateName = target.trim()
    ensureTemplates()

    if (!templateName) {
      // 列出所有模板
      const templates = getBuiltInTemplates()
      const customDir = getTemplatesDir()
      const customTemplates = existsSync(customDir)
        ? readdirSync(customDir).filter(f => f.endsWith('.md')).map(f => f.replace('.md', ''))
        : []
      return {
        type: 'text',
          value: [
          '📋 可用模板:',
        '',
        '内置模板:',
        ...templates.map(t => `  • ${t.name}`),
        ...(customTemplates.length > 0 ? ['', '自定义模板:', ...customTemplates.map(t => `  • ${t}`)] : []),
        '',
        '用法: /wiki template <模板名称>',
        '模板文件保存在: .wiki/templates/',
        ].join('\n'),
      }
    }

    // 使用模板创建文档
    const templates = getBuiltInTemplates()
    const tpl = templates.find(t => t.name === templateName)
    if (!tpl) {
      // 检查自定义模板
      const customPath = join(getTemplatesDir(), `${templateName}.md`)
      if (existsSync(customPath)) {
        const content = readFileSync(customPath, 'utf-8')
        const wikiDir = join(root, WIKI_DIR)
        if (!existsSync(wikiDir)) mkdirSync(wikiDir, { recursive: true })
        const newFileName = `${templateName}-${Date.now()}.md`
        writeFileSync(join(wikiDir, newFileName), content, 'utf-8')
        return { type: 'text', value: `✅ 从自定义模板创建: ${newFileName}` }
      }
      return { type: 'text', value: `❌ 模板不存在: ${templateName}\n使用 /wiki template 查看可用模板` }
    }

    const wikiDir = join(root, WIKI_DIR)
    if (!existsSync(wikiDir)) mkdirSync(wikiDir, { recursive: true })
    const newFileName = `${templateName}-${Date.now()}.md`
    writeFileSync(join(wikiDir, newFileName), tpl.content, 'utf-8')
    return { type: 'text', value: `✅ 从模板 "${templateName}" 创建: ${newFileName}` }
  }

  // ── 新命令: index ──────────────────────────────────────────
  if (cmd === 'index') {
    const entries = rebuildIndex()
    return {
      type: 'text',
      value: [
        '📇 文档索引已重建',
        '',
        `索引条目: ${entries.length}`,
        `存储位置: ${WIKI_DIR}/.index.json`,
        '',
        '索引内容预览 (前 20 条):',
        ...entries.slice(0, 20).map(e => `  [${e.file}] ${e.title} (${e.keywords.length} 关键词)`),
        ...(entries.length > 20 ? [`  ... 还有 ${entries.length - 20} 条`] : []),
      ].join('\n'),
    }
  }

  // ── 新命令: clean ──────────────────────────────────────────
  if (cmd === 'clean') {
    const result = cleanOrphanDocs()
    return { type: 'text', value: result }
  }

  return { type: 'text', value: '未知命令。使用 /wiki 查看帮助。' }
}

{
  const store = loadStore()
  const parts = (args || '').trim().split(/\s+/)
  const command = parts[0]?.toLowerCase() || 'help'
  const rest = parts.slice(1).join(' ')

  switch (command) {
    case 'help':
      return { type: 'text', value: renderHelp() }
    case 'save':
      return handleSave(store, parts.slice(1))
    case 'load':
      return handleLoad(store, rest)
    case 'list':
      return handleList(store)
    case 'delete':
      return handleDelete(store, rest)
    case 'view':
      return handleView(store, rest)
    case 'search':
      return handleSearch(store, rest)
    case 'filter':
      return handleFilter(store, parts.slice(1))
    case 'compare':
      return handleCompare(store, parts.slice(1))
    case 'merge':
      return handleMerge(store, parts.slice(1))
    case 'diff':
      return handleDiff(store, rest)
    case 'tags':
      return { type: 'text', value: listTags(store) }
    case 'categories':
      return { type: 'text', value: listCategories(store) }
    case 'tag-add':
      return handleTagAdd(store, parts.slice(1))
    case 'tag-remove':
      return handleTagRemove(store, parts.slice(1))
    case 'category':
      return handleSetCategory(store, parts.slice(1))
    case 'priority':
      return handleSetPriority(store, parts.slice(1))
    case 'template-list':
      return { type: 'text', value: listTemplates(store) }
    case 'template-create':
      return handleCreateTemplate(store, rest)
    case 'template-delete':
      return handleDeleteTemplate(store, rest)
    case 'template-use':
      return handleUseTemplate(store, rest)
    case 'export':
      return handleExport(store, parts.slice(1))
    case 'export-all':
      return handleExportAll(store, rest)
    case 'import':
      return handleImport(store, rest)
    case 'stats':
      return { type: 'text', value: formatStats(calculateStats(store)) }
    case 'timeline':
      return { type: 'text', value: formatTimeline(store) }
    case 'activity':
      return { type: 'text', value: formatActivity(calculateStats(store)) }
    case 'backup':
      return handleBackup(store)
    case 'backups':
      return { type: 'text', value: listBackupsText() }
    case 'restore':
      return handleRestore(store, rest)
    case 'settings':
      return { type: 'text', value: formatSettings(store.settings) }
    case 'set':
      return handleSetSetting(store, parts.slice(1))
    default:
      return { type: 'text', value: renderHelp() }
  }
}
